/* Theme tokens. visual.ts pushes the resolved palette onto the root as CSS
   custom properties (src/theme.ts); the fallbacks below are the light preset,
   so a render with no tokens set matches the pre-theme visual.
   Brand accent stays fixed - it is suite chrome, not a themeable surface. */
/* ========================================================================== */
/* BFUSION Project Lifecycle                                                 */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: var(--bf-bg, #FFFFFF);
  position: relative;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
/* ========================================================================== */
/* Lifecycle Container                                                       */
/* ========================================================================== */
.bfusion-lifecycle-wrap {
  width: 100%;
  height: 100%;
  overflow: auto;
  padding: 16px 20px;
  display: block;
}
.plc-container {
  width: 100%;
  min-height: 100%;
  display: flex;
  flex-direction: column;
}
/* ========================================================================== */
/* Progress Bar                                                              */
/* ========================================================================== */
.plc-progress-bar {
  margin-bottom: 20px;
  flex-shrink: 0;
}
.plc-progress-bar__track {
  height: 6px;
  border-radius: 3px;
  background: var(--bf-surface-alt, #F4F5F7);
  overflow: hidden;
  margin-bottom: 6px;
}
.plc-progress-bar__fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.plc-progress-bar__label {
  font-size: 11px;
  color: var(--bf-muted, #667079);
  font-weight: 500;
  letter-spacing: 0.2px;
}
/* ========================================================================== */
/* Timeline (horizontal — default)                                           */
/* ========================================================================== */
.plc-timeline {
  display: flex;
  align-items: flex-start;
  flex: 1;
  min-height: 0;
  padding: 8px 0;
  overflow-x: auto;
  overflow-y: visible;
  gap: 0;
}
.plc-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: 1 1 0;
  min-width: 80px;
  max-width: 180px;
  position: relative;
  transition: opacity 0.2s ease;
}
.plc-step__visual {
  display: flex;
  align-items: center;
  width: 100%;
  position: relative;
  height: 36px;
  justify-content: center;
}
/* ========================================================================== */
/* Cross-filtering: dimmed state                                             */
/* ========================================================================== */
.plc-step--dimmed {
  opacity: 0.3;
  pointer-events: auto;
}
/* ========================================================================== */
/* Nodes                                                                     */
/* ========================================================================== */
.plc-node {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  cursor: pointer;
  transition: transform 0.2s ease;
}
.plc-node:hover {
  transform: scale(1.15);
}
.plc-node__circle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 3px solid;
  transition: box-shadow 0.2s ease;
  position: relative;
}
.plc-node--completed .plc-node__circle {
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.3);
}
.plc-node--active .plc-node__circle {
  box-shadow: 0 2px 12px rgba(59, 130, 246, 0.4);
  animation: nodeGlow 2s ease-in-out infinite;
}
.plc-node--upcoming .plc-node__circle {
  background: var(--bf-tile, #FFFFFF) !important;
  border-color: var(--bf-rule, #E5E7EB) !important;
}
.plc-node__check {
  display: block;
}
.plc-node__pulse {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--bf-tile, #FFFFFF);
  animation: pulse 2s ease-in-out infinite;
}
@keyframes pulse {
  0%,
  100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(1.3);
    opacity: 0.7;
  }
}
@keyframes nodeGlow {
  0%,
  100% {
    box-shadow: 0 2px 8px rgba(59, 130, 246, 0.3);
  }
  50% {
    box-shadow: 0 2px 20px rgba(59, 130, 246, 0.5);
  }
}
/* Gate (diamond) */
.plc-node--gate .plc-node__diamond {
  filter: drop-shadow(0 2px 6px rgba(139, 92, 246, 0.3));
  transition: filter 0.2s ease;
}
.plc-node--gate:hover .plc-node__diamond {
  filter: drop-shadow(0 3px 10px rgba(139, 92, 246, 0.5));
}
.plc-node--gate.plc-node--upcoming .plc-node__diamond rect {
  fill: var(--bf-rule, #E5E7EB);
}
/* ========================================================================== */
/* Connectors                                                                */
/* ========================================================================== */
.plc-connector {
  flex: 1;
  height: 3px;
  border-radius: 1.5px;
  min-width: 12px;
  z-index: 1;
  transition: background 0.3s ease;
}
/* Connector fill animation */
.plc-connector--animated {
  animation: connectorFill 0.8s ease-out forwards;
}
@keyframes connectorFill {
  from {
    transform: scaleX(0);
    transform-origin: left center;
  }
  to {
    transform: scaleX(1);
    transform-origin: left center;
  }
}
/* ========================================================================== */
/* Step Content (labels below nodes)                                         */
/* ========================================================================== */
.plc-step__content {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-top: 10px;
  text-align: center;
  width: 100%;
  padding: 0 4px;
}
.plc-step__name {
  font-size: 12px;
  font-weight: 600;
  color: var(--bf-strong, #1F2A44);
  line-height: 1.3;
  margin-bottom: 4px;
  word-wrap: break-word;
  overflow-wrap: break-word;
  max-width: 100%;
}
.plc-step__badge {
  display: inline-block;
  padding: 1px 8px;
  border-radius: 10px;
  font-size: 9px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  margin-bottom: 3px;
}
.plc-step__badge--gate {
  /* colors set inline via style */
}
.plc-step__badge--approved {
  background: rgba(16, 185, 129, 0.1);
  color: #059669;
}
.plc-step__badge--rejected {
  background: rgba(239, 68, 68, 0.1);
  color: #dc2626;
}
.plc-step__badge--pending {
  background: rgba(245, 158, 11, 0.1);
  color: #d97706;
}
.plc-step__date {
  font-size: 10px;
  color: var(--bf-muted, #667079);
  line-height: 1.3;
}
.plc-step__date--end {
  color: var(--bf-muted, #667079);
}
/* Inline date row (vertical layout) */
.plc-step__dates-row {
  display: flex;
  align-items: center;
  gap: 0;
  flex-wrap: wrap;
  font-size: 10px;
  line-height: 1.3;
  margin-bottom: 2px;
}
.plc-step__date-sep {
  color: var(--bf-rule, #E5E7EB);
  margin: 0 3px;
  font-size: 9px;
}
/* ========================================================================== */
/* Duration                                                                  */
/* ========================================================================== */
.plc-step__duration {
  font-size: 9px;
  color: var(--bf-muted, #667079);
  font-weight: 500;
  font-style: italic;
  line-height: 1.3;
  margin-top: 1px;
  padding: 1px 6px;
  background: rgba(148, 163, 184, 0.08);
  border-radius: 8px;
}
/* ========================================================================== */
/* Comment Callouts                                                          */
/* ========================================================================== */
.plc-step__callout {
  position: relative;
  margin-top: 6px;
  width: 100%;
  max-width: 150px;
}
.plc-step__callout-arrow {
  width: 8px;
  height: 8px;
  background: var(--bf-tile, #FFFFFF);
  border-top: 1px solid var(--bf-rule, #E5E7EB);
  border-left: 1px solid var(--bf-rule, #E5E7EB);
  transform: rotate(45deg);
  margin: 0 auto -5px;
  position: relative;
  z-index: 1;
}
.plc-step__callout-body {
  background: var(--bf-tile, #FFFFFF);
  border: 1px solid var(--bf-rule, #E5E7EB);
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 10px;
  color: var(--bf-muted, #667079);
  line-height: 1.4;
  text-align: center;
  word-wrap: break-word;
  overflow-wrap: break-word;
  position: relative;
  z-index: 0;
}
/* ========================================================================== */
/* Legend                                                                     */
/* ========================================================================== */
.plc-legend {
  display: flex;
  gap: 16px;
  margin-top: auto;
  margin-bottom: 24px;
  /* clear the license badge */
  padding-top: 16px;
  flex-shrink: 0;
  flex-wrap: wrap;
}
.plc-legend__item {
  display: flex;
  align-items: center;
  gap: 5px;
}
.plc-legend__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.plc-legend__label {
  font-size: 10px;
  color: var(--bf-muted, #667079);
  font-weight: 500;
}
/* ========================================================================== */
/* Staggered Animation                                                       */
/* ========================================================================== */
.plc-step--animate {
  opacity: 0;
  transform: translateY(8px);
  animation: stepFadeIn 0.4s ease forwards;
}
.plc-container--vertical .plc-step--animate {
  transform: translateX(-8px);
  animation: stepSlideInV 0.4s ease forwards;
}
@keyframes stepFadeIn {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes stepSlideInV {
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
/* ========================================================================== */
/* Compact Mode                                                              */
/* ========================================================================== */
.plc-container--compact .plc-progress-bar {
  margin-bottom: 10px;
}
.plc-container--compact .plc-step__content {
  margin-top: 6px;
}
.plc-container--compact .plc-step__name {
  font-size: 10px;
}
.plc-container--compact .plc-node__circle {
  width: 24px;
  height: 24px;
  border-width: 2px;
}
.plc-container--compact .plc-node__check {
  width: 10px;
  height: 10px;
}
.plc-container--compact .plc-node__pulse {
  width: 7px;
  height: 7px;
}
.plc-container--compact .plc-node--gate .plc-node__diamond {
  width: 22px;
  height: 22px;
}
.plc-container--compact .plc-step {
  min-width: 56px;
}
.plc-container--compact .plc-connector {
  height: 2px;
}
.plc-container--compact .plc-step__visual {
  height: 28px;
}
/* ========================================================================== */
/* Vertical Layout                                                           */
/* ========================================================================== */
.plc-container--vertical .plc-timeline {
  flex-direction: column;
  align-items: flex-start;
  overflow-x: visible;
  overflow-y: auto;
  padding: 0;
  gap: 0;
}
.plc-container--vertical .plc-step {
  flex-direction: row;
  align-items: flex-start;
  min-width: unset;
  max-width: 100%;
  width: 100%;
  min-height: 48px;
}
.plc-container--vertical .plc-step__visual {
  flex-direction: column;
  align-items: center;
  width: 36px;
  min-width: 36px;
  height: auto;
  flex-shrink: 0;
}
.plc-container--vertical .plc-connector {
  width: 3px;
  height: auto;
  flex: 1;
  min-width: unset;
  min-height: 12px;
  border-radius: 1.5px;
}
.plc-container--vertical .plc-connector--animated {
  animation: connectorFillVertical 0.8s ease-out forwards;
}
.plc-container--vertical .plc-step__content {
  align-items: flex-start;
  text-align: left;
  margin-top: 0;
  margin-left: 12px;
  padding: 4px 0 16px 0;
  width: auto;
  flex: 1;
  min-width: 0;
}
.plc-container--vertical .plc-step__name {
  margin-bottom: 3px;
  font-size: 13px;
}
.plc-container--vertical .plc-step__badge {
  margin-bottom: 3px;
}
.plc-container--vertical .plc-step__duration {
  margin-top: 2px;
}
.plc-container--vertical .plc-step__callout {
  max-width: 320px;
  margin-top: 8px;
}
.plc-container--vertical .plc-step__callout-arrow {
  margin: 0 0 -5px 14px;
}
.plc-container--vertical .plc-step__callout-body {
  text-align: left;
}
.plc-container--vertical .plc-legend {
  padding-left: 48px;
}
@keyframes connectorFillVertical {
  from {
    transform: scaleY(0);
    transform-origin: top center;
  }
  to {
    transform: scaleY(1);
    transform-origin: top center;
  }
}
/* ========================================================================== */
/* High Contrast Mode                                                        */
/* ========================================================================== */
.plc-container--hc .plc-node__circle {
  border-width: 3px;
}
.plc-container--hc .plc-node--upcoming .plc-node__circle {
  background: transparent !important;
  border-style: dashed !important;
}
.plc-container--hc .plc-step__name {
  color: inherit;
}
.plc-container--hc .plc-step__date,
.plc-container--hc .plc-step__date--end,
.plc-container--hc .plc-step__duration,
.plc-container--hc .plc-progress-bar__label,
.plc-container--hc .plc-legend__label {
  color: inherit;
}
.plc-container--hc .plc-tooltip {
  background: var(--bf-band, #1F2A44);
  color: #fff;
  border: 2px solid var(--bf-tile, #FFFFFF);
}
.plc-container--hc .plc-tooltip__label {
  color: var(--bf-rule, #E5E7EB);
}
.plc-container--hc .plc-step__callout-body {
  border-width: 2px;
  color: inherit;
}
.plc-container--hc .plc-step__callout-arrow {
  border-width: 2px;
}
.plc-container--hc .plc-progress-bar__track {
  border: 1px solid;
}
.plc-container--hc .plc-step__badge {
  border: 1px solid;
}
/* ========================================================================== */
/* Landing Page                                                              */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: var(--bf-bg, #FFFFFF);
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #FF5500;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: var(--bf-text, #242424);
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: var(--bf-muted, #667079);
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: var(--bf-text, #242424);
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: var(--bf-rule, #E5E7EB);
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: var(--bf-muted, #667079);
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: var(--bf-muted, #667079);
}
/* ========================================================================== */
/* License Badge & Watermark                                                  */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: transparent;
  border: none;
  color: var(--bf-muted, #667079);
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
/* ========================================================================== */
/* Empty Data State (cross-filter excluded everything)                        */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: var(--bf-muted, #667079);
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
